class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        ops = 0
        for col in zip(*grid):
            prev = -1
            for v in col:
                if v <= prev:
                    ops += prev + 1 - v
                    prev += 1
                else:
                    prev = v
        return ops

c.cpp:
class Solution {
public:
    int minimumOperations(vector<vector<int>>& grid) {
        long long ops = 0;
        int m = grid.size(), n = grid[0].size();
        for (int j = 0; j < n; j++) {
            long long prev = -1;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] <= prev) {
                    ops += prev + 1 - grid[i][j];
                    prev += 1;
                } else {
                    prev = grid[i][j];
                }
            }
        }
        return (int)ops;
    }
};

